function isCompanion(id){ return +id===COMPANION_ID; }
function setCompanionStar(n){
  COMPANION_STAR = Math.max(1, Math.min(5, n));
  COMPANION.stars = COMPANION_STAR;
  COMPANION.img = COMPANION_IMGS[COMPANION_STAR];
  LS.set('dinodoku-companion', JSON.stringify({star:COMPANION_STAR}));
}
function refreshCompanionCells(){ /* 進化後同步圖鑑格子的星級框與圖片 */
  ['dex-','df-'].forEach(pre=>{
    const el=$(pre+COMPANION_ID);
    if(!el) return;
    el.className='dex-cell p3d s'+COMPANION_STAR+' got';
    const im=el.querySelector('img'); if(im) im.src=COMPANION.img;
  });
}
function evolveCompanion(){
  const star=COMPANION_STAR;
  if(star>=5){ SFX.wrong(); return; }
  const need=EVOLVE_NEED[star+1];
  if(!ECON.devFree && (ECON.potions||0)<need){ floatText($('dexd-extra'),'進化藥水不足（需要 🧪×'+need+'）','#d64545'); SFX.wrong(); return; }
  if(!ECON.devFree) ECON.potions-=need;
  setCompanionStar(star+1);
  econSave(); econRender();
  SFX.win(); if(typeof confetti==='function') confetti();
  doBuddyChat('我進化了！現在是 <b>'+COMPANION_STAR+'★</b> 的我！✨');
  if(typeof renderBuddy==='function') renderBuddy();
  refreshCompanionCells();
  if(dexdMon && isCompanion(dexdMon.id)) showCompanionDetail(dexdMon);
}
function allMonsWithCompanion(){ return [COMPANION].concat(allMons()); } /* 圖鑑顯示序：伴伴永遠第一位（No.000） */

