/* ---------- 尋龍地圖引擎：15 個地形區塊（SVG 覆蓋層） ---------- */
/* 背景為 assets/map.png 手繪大地圖，地形本身即含浮空島／雪山／火山／沙漠等場景，不需再加 emoji 裝飾 */
const MAP_DECOR=[];
/* 共享邊緣的有機圓滑：每段邊以「中點＋确定性偏移」當二次曲線控制點，相鄰區塊走同一條邊必然密合 */
function mapEdgeCtrl(ax,ay,bx,by){
  let x1=ax,y1=ay,x2=bx,y2=by;
  if(x2<x1 || (x2===x1 && y2<y1)){ x1=bx; y1=by; x2=ax; y2=ay; }
  const h=((x1*73856093) ^ (y1*19349663) ^ (x2*83492791) ^ (y2*2971215073))>>>0;
  const j=((h%2000)/1000-1)*3.4; /* ±3.4 使用者單位的隨機彎曲 */
  const dx=x2-x1, dy=y2-y1, len=Math.hypot(dx,dy)||1;
  return [(x1+x2)/2 - dy/len*j, (y1+y2)/2 + dx/len*j];
}
/* 頂點（x%,y%）→ viewBox 200×300 的封閉平滑路徑 */
function mapRegionPath(pts){
  const P=pts.map(p=>[p[0]*2, p[1]*3]);
  let d='M '+P[0][0].toFixed(1)+' '+P[0][1].toFixed(1);
  for(let i=0;i<P.length;i++){
    const a=P[i], b=P[(i+1)%P.length];
    const c=mapEdgeCtrl(a[0],a[1],b[0],b[1]);
    d+=' Q '+c[0].toFixed(1)+' '+c[1].toFixed(1)+' '+b[0].toFixed(1)+' '+b[1].toFixed(1);
  }
  return d+' Z';
}
function renderMap(){
  const box=$('map-nodes'); if(!box) return;
  const dc=$('map-decor');
  if(dc && !dc.children.length) MAP_DECOR.forEach(d=>{ const s=document.createElement('span'); s.textContent=d[0]; s.style.left=d[1]+'%'; s.style.top=d[2]+'%'; dc.appendChild(s); });
  let svg='<svg id="map-svg" viewBox="0 0 200 300" preserveAspectRatio="none">';
  for(let n=4;n<=13;n++){
    const meta=REGION_META[n], geo=MAP_REGIONS[n];
    if(!meta || !geo) continue;
    const rec=lvRec(n);
    const cleared=rec.total>0;
    const unlocked=isUnlocked(n);
    const cls=cleared?'clear':(unlocked?'new':'lock');
    const sub = !unlocked ? '🔒 未探索'
      : cleared ? ('✓ 已通關'+(rec.best?' '+fmtSec(rec.best):''))
      : (n+'×'+n+(n<=5?'':' '+n+':00'));
    const tip=meta.name+' '+n+'×'+n+' · '+sub;
    const lx=geo.lab[0]*2, ly=geo.lab[1]*3;
    svg+='<g class="mreg '+cls+'" data-n="'+n+'" role="button" tabindex="0" aria-label="'+tip+'">'
      +'<path d="'+mapRegionPath(geo.pts)+'" fill="'+geo.col+'"/>'
      +'<text class="mr-name" x="'+lx.toFixed(1)+'" y="'+ly.toFixed(1)+'">'+meta.name+'</text>'
      +'<text class="mr-sub" x="'+lx.toFixed(1)+'" y="'+(ly+8).toFixed(1)+'">'+sub+'</text>'
      +'</g>';
  }
  svg+='</svg>';
  box.innerHTML=svg;
  const svgEl=box.querySelector('#map-svg');
  /* 點在標稱多邊形內判定（射線法）；多邊形依畫序以大號（後畫）優先 */
  const pip=(x,y,pts)=>{
    let inside=false;
    for(let i=0,j=pts.length-1;i<pts.length;j=i++){
      const xi=pts[i][0], yi=pts[i][1], xj=pts[j][0], yj=pts[j][1];
      if(((yi>y)!==(yj>y)) && (x<(xj-xi)*(y-yi)/(yj-yi)+xi)) inside=!inside;
    }
    return inside;
  };
  const regionAt=(x,y)=>{ /* x,y：地圖百分比 0~100 */
    for(let n=18;n>=4;n--){ const geo=MAP_REGIONS[n]; if(geo && pip(x,y,geo.pts)) return n; }
    return null;
  };
  const tryGo=n=>{
    const g=svgEl.querySelector('g[data-n="'+n+'"]');
    if(!isUnlocked(n)){
      SFX.wrong();
      if(g){ g.classList.add('shake'); setTimeout(()=>g.classList.remove('shake'),330); }
      if(typeof doBuddyChat==='function' && BUDDY.id) doBuddyChat('那個區域還不能去～先通過前面的區域吧！');
      return;
    }
    openLevel(n);
  };
  /* 進關互動：以 pointerup 為主（滑鼠／觸控／筆通用，事件序列中的 DOM 變動不會取消它），
     click 僅作不支援 pointer 事件的舊瀏覽器備援（600ms 內已處理過就忽略，避免重複進關） */
  let lastNav=0, pDown=null;
  const navFromEvent=e=>{
    const r=svgEl.getBoundingClientRect();
    if(!r.width || !r.height) return;
    const g=e.target && e.target.closest ? e.target.closest('g.mreg') : null;
    const n=g ? +g.dataset.n : regionAt((e.clientX-r.left)/r.width*100, (e.clientY-r.top)/r.height*100);
    if(n) tryGo(n);
  };
  svgEl.addEventListener('pointerdown', e=>{ pDown=(e.isPrimary && e.button===0) ? {x:e.clientX,y:e.clientY} : null; });
  svgEl.addEventListener('pointercancel', ()=>{ pDown=null; });
  svgEl.addEventListener('pointerup', e=>{
    if(!pDown) return;
    const moved=Math.hypot(e.clientX-pDown.x, e.clientY-pDown.y);
    pDown=null;
    lastNav=Date.now();
    if(moved>12) return; /* 拖曳捲動地圖，不是點選 */
    navFromEvent(e);
  });
  svgEl.addEventListener('click', e=>{
    if(Date.now()-lastNav<600) return;
    navFromEvent(e);
  });
  box.querySelectorAll('.mreg').forEach(g=>{
    const n=+g.dataset.n;
    g.addEventListener('keydown', e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); tryGo(n); } });
  });
  /* 滑鼠懸停時把區塊移到最上層（僅限真實滑鼠），讓其邊線與文字不被鄰塊蓋住 */
  svgEl.addEventListener('pointerover', e=>{
    if(e.pointerType!=='mouse') return;
    const g=e.target.closest && e.target.closest('g.mreg');
    if(g && g.parentNode) g.parentNode.appendChild(g);
  });
  /* 自動捲動：讓最前面的可玩區域（新手＝4×4 起源地）落在可視區中央 */
  const map=$('map');
  if(map){
    const target=Math.max(4, Math.min(13, PROG.max||4));
    const geo=MAP_REGIONS[target];
    const inner=map.querySelector('.map-inner');
    if(geo && inner && inner.offsetHeight>map.clientHeight){
      let cy=0; geo.pts.forEach(p=>{ cy+=p[1]; }); cy/=geo.pts.length; /* 區塊中心 y% */
      map.scrollTop=Math.max(0, cy/100*inner.offsetHeight - map.clientHeight*0.5);
    } else if(map.scrollTop>0 && inner && inner.offsetHeight<=map.clientHeight){
      map.scrollTop=0;
    }
  }
}
