/* ---------- 開場：滿版 logo 展示 0.5 秒，再縮小飛進主選單左上 ---------- */
(function(){
  const sp=$('splash');
  if(!sp){ document.body.classList.remove('splash-on'); introStoryOnce(); return; }
  const img=sp.querySelector('img'), bg=sp.querySelector('.sp-bg');
  const target=document.querySelector('#menu-logo img');
  const HOLD=500, FLY=680;
  let done=false, safety=0;

  function finish(){
    if(done) return;
    done=true;
    clearTimeout(safety);
    sp.remove();
    document.body.classList.remove('splash-on');
    introStoryOnce();
  }
  safety=setTimeout(finish, 8000); /* 保險：任何異常都不會卡在開場畫面 */
  function ready(el, ms){
    return new Promise(res=>{
      if(!el || (el.complete && el.naturalWidth>0)){ res(); return; }
      const t=setTimeout(res, ms);
      el.addEventListener('load', ()=>{ clearTimeout(t); res(); }, {once:true});
      el.addEventListener('error', ()=>{ clearTimeout(t); res(); }, {once:true});
    });
  }
  function fly(){
    /* 先停掉開場淡入動畫並強制重排，否則起點尺寸會帶著動畫中的縮放比例，落點會偏移 */
    img.style.animation='none';
    void img.offsetWidth;
    const a=img.getBoundingClientRect(), b=target && target.getBoundingClientRect();
    if(!a.width || !a.height || !b || !b.width){ finish(); return; }
    if(bg){ bg.style.transition='opacity '+Math.round(FLY*.7)+'ms ease'; bg.style.opacity='0'; }
    img.style.transformOrigin='0 0';
    img.style.transition='transform '+FLY+'ms cubic-bezier(.22,.85,.25,1)';
    img.style.transform='translate('+(b.left-a.left)+'px,'+(b.top-a.top)+'px) scale('+(b.width/a.width)+','+(b.height/a.height)+')';
    setTimeout(finish, FLY+60);
  }
  Promise.all([ready(img,900), ready(target,900)]).then(()=>setTimeout(fly, HOLD));
})();


/* ---------- 伴伴（一星）2.5D 生動化：偶爾眨眼／點頭／甩頭／大笑 ---------- */
(function(){
  const ACTS = ['bb-blink','bb-nod','bb-shake','bb-laugh'];
  const DUR = {'bb-blink':360,'bb-nod':770,'bb-shake':870,'bb-laugh':1330};
  let busy = false;

  function wrap(img){
    if(!img || (img.parentNode && img.parentNode.classList && img.parentNode.classList.contains('bb-alive'))) return;
    const w = document.createElement('span');
    w.className = 'bb-alive';
    img.parentNode.insertBefore(w, img);
    w.appendChild(img);
    ['l','r'].forEach(s=>{ const lid=document.createElement('i'); lid.className='bb-lid '+s; lid.setAttribute('aria-hidden','true'); w.appendChild(lid); });
  }

  function visible(w){
    if(!w.offsetWidth || !w.getClientRects().length) return false;
    for(let p=w; p && p!==document.body; p=p.parentNode){
      const s=getComputedStyle(p);
      if(s.display==='none' || s.visibility==='hidden') return false;
    }
    return true;
  }

  function aliveEls(){
    const out=[];
    document.querySelectorAll('.bb-alive').forEach(w=>{
      const im=w.querySelector('img');
      if(im && im.src.indexOf('DFD-000_')>=0 && im.src.indexOf('_1star.png')>=0 && visible(w)) out.push(w);
    });
    return out;
  }

  function fire(cls){
    const els=aliveEls(); if(!els.length) return;
    busy=true;
    els.forEach(w=>{ w.classList.remove.apply(w.classList, ACTS); void w.offsetWidth; w.classList.add(cls); });
    setTimeout(()=>{ els.forEach(w=>w.classList.remove(cls)); busy=false; }, DUR[cls]||800);
  }

  function pick(){
    const r=Math.random();
    if(r<.48) return 'bb-blink';
    if(r<.70) return 'bb-nod';
    if(r<.90) return 'bb-shake';
    return 'bb-laugh';
  }

  function loop(){
    setTimeout(loop, 3400+Math.random()*5000);
    if(busy || document.hidden) return;
    fire(pick());
  }

  function init(){
    wrap($('dlg-img'));
    wrap($('dexd-img'));
    setTimeout(loop, 1800);
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', init); else init();

  window.bbTest = fire; /* 工程驗證：bbTest('bb-shake') 等 */
})();


